/**
* Utilitário de Exportação e Importação de Dados em Lote (Excel / CSV)
* Silva & Associados Advocacia Estratégica
*/
var downloadCSV = (nomeArquivo, conteudoCSV) => {
	const blob = new Blob(["﻿" + conteudoCSV], { type: "text/csv;charset=utf-8;" });
	const url = URL.createObjectURL(blob);
	const link = document.createElement("a");
	link.href = url;
	link.download = nomeArquivo;
	link.style.display = "none";
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	URL.revokeObjectURL(url);
};
var escapeCSV = (valor) => {
	if (valor === null || valor === void 0) return "";
	const stringValor = String(valor).trim();
	if (stringValor.includes(";") || stringValor.includes("\n") || stringValor.includes("\"")) return `"${stringValor.replace(/"/g, "\"\"")}"`;
	return stringValor;
};
var exportarProcessosCSV = (processos) => {
	const headers = [
		"CNJ",
		"Cliente",
		"Polo",
		"Área",
		"Vara / Foro",
		"Fase Processual",
		"Valor da Causa",
		"Última Movimentação",
		"Data da Movimentação"
	];
	const linhas = (processos || []).map((p) => [
		escapeCSV(p.cnj),
		escapeCSV(p.cliente),
		escapeCSV(p.polo),
		escapeCSV(p.area),
		escapeCSV(p.vara),
		escapeCSV(p.fase),
		escapeCSV(p.valorCausa),
		escapeCSV(p.ultimaMov),
		escapeCSV(p.dataMov)
	].join(";"));
	const conteudo = [headers.join(";"), ...linhas].join("\r\n");
	downloadCSV(`processos_gestao_juridica_${(/* @__PURE__ */ new Date()).toISOString().slice(0, 10)}.csv`, conteudo);
};
