//#region src/utils/digitalSignature.js
var gerarHashSHA256 = async (texto) => {
	if (window.crypto && window.crypto.subtle) try {
		const data = new TextEncoder().encode(texto || String(Date.now()));
		const hashBuffer = await window.crypto.subtle.digest("SHA-256", data);
		return Array.from(new Uint8Array(hashBuffer)).map((b) => b.toString(16).padStart(2, "0")).join("");
	} catch (e) {
		console.warn("Crypto API fallback", e);
	}
	let hash = 0;
	for (let i = 0; i < texto.length; i++) {
		const char = texto.charCodeAt(i);
		hash = (hash << 5) - hash + char;
		hash = hash & hash;
	}
	return `sha256_${Math.abs(hash).toString(16).padStart(8, "0")}a9c84e1b2f83d71e654b09c54e3f218a901d84e${Date.now().toString(16)}`.slice(0, 64);
};
var gerarIdEnvelope = () => {
	return `ENV-${(/* @__PURE__ */ new Date()).getFullYear()}-${Math.floor(1e3 + Math.random() * 9e3)}`;
};
